mapper.select:
SELECT 'CROP_VARIETY' resource_type,fc.farm_id,fc.crop_id resource_id,CONCAT('CROP:',c.name) name,fc.active_yn active,'N' deleted FROM farm_crop fc JOIN crop c ON c.id=fc.crop_id WHERE fc.farm_id  AND 'CROP_VARIETY' IN #{s}
UNION ALL SELECT 'CROP_VARIETY',fv.farm_id,fv.variety_id,CONCAT('VARIETY:',fv.crop_id,':',v.name),fv.active_yn,'N' FROM farm_crop_variety fv JOIN crop_variety v ON v.id=fv.variety_id WHERE fv.farm_id  AND 'CROP_VARIETY' IN #{s}
UNION ALL SELECT 'SEASON',s.farm_id,s.id,s.name,IF(s.status='ACTIVE' AND s.deleted_at IS NULL,'Y','N'),IF(s.deleted_at IS NULL,'N','Y') FROM crop_season s WHERE s.farm_id  AND 'SEASON' IN #{x}
UNION ALL SELECT 'WORK_TYPE',w.farm_id,w.id,w.name,w.active_yn,'N' FROM work_type w WHERE w.farm_id  AND 'WORK_TYPE' IN #{x}
UNION ALL SELECT 'CUSTOMER',c.farm_id,c.id,c.name,IF(c.active_yn='Y' AND c.deleted_at IS NULL,'Y','N'),IF(c.deleted_at IS NULL,'N','Y') FROM customer c WHERE c.farm_id  AND 'CUSTOMER' IN #{x}
UNION ALL SELECT 'MATERIAL',m.farm_id,m.id,m.name,IF(m.active_yn='Y' AND m.deleted_at IS NULL,'Y','N'),IF(m.deleted_at IS NULL,'N','Y') FROM material m WHERE m.farm_id  AND 'MATERIAL' IN #{x}
ORDER BY resource_type,farm_id,resource_id

SELECT 'WORK' record_type,l.id record_id,l.farm_id,l.zone_id,l.work_date record_date,l.created_role,NULL unit,NULL quantity,NULL gross_amount,NULL fee_amount,NULL net_amount,l.variety_id,v.name variety_name,z.id zone_breakdown_id,z.name zone_name,NULL customer_id,NULL customer_name FROM work_log l LEFT JOIN farm_zone z ON z.id=l.zone_id LEFT JOIN crop_variety v ON v.id=l.variety_id WHERE l.organization_id=#{organizationId} AND l.deleted_at IS NULL AND l.work_date>=#{start} AND l.work_date<#{endExclusive}
UNION ALL SELECT 'PEST_CONTROL',l.id,l.farm_id,l.zone_id,l.apply_date,l.created_role,NULL,NULL,NULL,NULL,NULL,l.variety_id,v.name,z.id,z.name,NULL,NULL FROM pest_control_log l LEFT JOIN farm_zone z ON z.id=l.zone_id LEFT JOIN crop_variety v ON v.id=l.variety_id WHERE l.organization_id=#{organizationId} AND l.deleted_at IS NULL AND l.apply_date>=#{start} AND l.apply_date<#{endExclusive}
UNION ALL SELECT 'HARVEST',l.id,l.farm_id,l.zone_id,l.harvest_date,l.created_role,LOWER(TRIM(l.unit)),l.quantity,NULL,NULL,NULL,l.variety_id,v.name,z.id,z.name,NULL,NULL FROM harvest_log l LEFT JOIN farm_zone z ON z.id=l.zone_id LEFT JOIN crop_variety v ON v.id=l.variety_id WHERE l.organization_id=#{organizationId} AND l.deleted_at IS NULL AND l.harvest_date>=#{start} AND l.harvest_date<#{endExclusive}
UNION ALL SELECT 'SALES',l.id,l.farm_id,NULL,l.sales_date,l.created_role,LOWER(TRIM(l.unit)),l.quantity,l.gross_amount,l.fee_amount,l.net_amount,NULL,NULL,NULL,NULL,l.customer_id,c.name FROM sales_log l LEFT JOIN customer c ON c.id=l.customer_id WHERE l.organization_id=#{organizationId} AND l.deleted_at IS NULL AND l.sales_date>=#{start} AND l.sales_date<#{endExclusive}
